import {BUILD_ID} from './build-id.mjs';
let installPrompt,registration,notifiedWorker,applying=false;
const standalone=matchMedia('(display-mode:standalone)');
function updateInstall(){const installed=standalone.matches||navigator.standalone===true||localStorage.getItem('ems.pwa.installed')==='true';for(const button of document.querySelectorAll('[data-install]'))button.hidden=installed;}
addEventListener('appinstalled',()=>{localStorage.setItem('ems.pwa.installed','true');installPrompt=null;updateInstall();});standalone.addEventListener('change',updateInstall);updateInstall();
const message=document.createElement('p');message.className='pwa-notice';message.hidden=true;message.setAttribute('role','status');const text=document.createElement('span'),close=document.createElement('button'),apply=document.createElement('button');close.textContent='Закрыть';close.onclick=()=>{message.hidden=true;};apply.textContent='Обновить';apply.dataset.applyUpdate='';apply.hidden=true;message.append(text,close,apply);document.body.append(message);
function notice(value,update=false){text.textContent=value;apply.hidden=!update;message.hidden=false;}
function available(force=false){if(!registration?.waiting)return false;if(force||notifiedWorker!==registration.waiting){notifiedWorker=registration.waiting;notice('Доступна новая версия EMS. Сохраните изменения во всех вкладках и нажмите «Обновить».',true);}return true;}
async function serverRelease(){const response=await fetch('/api/release',{cache:'no-store'});if(!response.ok)throw Error('Release unavailable');const value=await response.json();if(value.schemaVersion!=='ems-release/1'||!(/^[a-f0-9]{24}$/.test(value.assets))||value.release!==null&&!(/^[a-f0-9]{40}$/.test(value.release)))throw Error('Invalid release metadata');return value;}
function workerVersion(worker){return new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>{channel.port1.close();reject(Error('Worker version timeout'));},3000);channel.port1.onmessage=event=>{clearTimeout(timer);channel.port1.close();event.data?.schemaVersion==='ems-shell/1'?resolve(event.data.revision):reject(Error('Invalid worker version'));};worker.postMessage({type:'version'},[channel.port2]);});}
apply.onclick=async()=>{const worker=registration?.waiting??navigator.serviceWorker?.controller;if(applying||!worker)return;applying=true;apply.disabled=true;let reload,requested=false;try{const release=await serverRelease();if(await workerVersion(worker)!==release.assets){await registration?.update();notice('Версия на сервере изменилась. Повторите проверку обновления.');return;}if(registration?.waiting!==worker){location.reload();return;}reload=()=>location.reload();navigator.serviceWorker.addEventListener('controllerchange',reload,{once:true});worker.postMessage({type:'activate'});requested=true;}catch{if(reload)navigator.serviceWorker.removeEventListener('controllerchange',reload);notice('Не удалось проверить обновление. Подключитесь к сети и повторите проверку.');}finally{if(!requested){applying=false;apply.disabled=false;}}};
addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;localStorage.removeItem('ems.pwa.installed');updateInstall();});
document.addEventListener('ems-install',async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;}else if(matchMedia('(display-mode:standalone)').matches)notice('EMS уже открыт как приложение.');else notice('В меню браузера выберите «Установить приложение» или «На экран Домой».');});
addEventListener('offline',()=>notice('Нет сети. Сохранённые проекты доступны на этом устройстве.'));
addEventListener('online',()=>{message.hidden=true;available();});
const ready='serviceWorker' in navigator?navigator.serviceWorker.register('/web/service-worker.mjs',{scope:'/',type:'module',updateViaCache:'none'}).then(value=>{registration=value;available();const watch=worker=>worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)available();});watch(registration.installing);registration.addEventListener('updatefound',()=>watch(registration.installing));return value;}).catch(()=>{notice('Офлайн-режим пока недоступен. Продолжайте работу в браузере.');return null;}):Promise.resolve(null);
if(document.getElementById('project-list')){
 const version=document.createElement('p'),label=document.createElement('span'),check=document.createElement('button');version.className='pwa-version';label.dataset.appVersion=BUILD_ID;label.textContent='Версия '+BUILD_ID.slice(0,8);check.textContent='Проверить обновление';check.dataset.checkUpdate='';version.append(label,check);document.querySelector('main').prepend(version);
 check.onclick=async()=>{check.disabled=true;try{const release=await serverRelease();await ready;await registration?.update();if(!available(true)){if(release.assets===BUILD_ID)notice('Установлена последняя версия EMS.');else if(!registration?.installing&&navigator.serviceWorker?.controller&&await workerVersion(navigator.serviceWorker.controller)===release.assets)notice('Доступна новая версия EMS. Сохраните изменения во всех вкладках и нажмите «Обновить».',true);else notice('Загружается обновление EMS. Сохранённые проекты остаются на устройстве.');}}catch{notice('Не удалось проверить обновление. Сохранённые проекты доступны без сети.');}finally{check.disabled=false;}};
}
